  "enterprises": {img:"🏢", ex5:[{t:1,en:"Small enterprises are vital for the economy.",kr:"소규모 기업들은 경제에 필수적이다."},{t:2,en:"Many new enterprises are starting up in this city.",kr:"이 도시에는 많은 새로운 기업들이 생겨나고 있다."},{t:3,en:"She manages several successful enterprises.",kr:"그녀는 몇 개의 성공적인 기업들을 경영한다."},{t:4,en:"Government supports new enterprises with funding.",kr:"정부는 새로운 기업들을 자금으로 지원한다."},{t:5,en:"These enterprises focus on environmental solutions.",kr:"이 기업들은 환경 솔루션에 중점을 둔다."}]},
  "enterprising": {img:"💡", ex5:[{t:1,en:"She is a very enterprising young woman with many business ideas.",kr:"그녀는 사업 아이디어가 많은 매우 진취적인 젊은 여성이다."},{t:2,en:"His enterprising spirit led him to start his own company.",kr:"그의 기업가 정신은 그가 자신의 회사를 시작하도록 이끌었다."},{t:3,en:"The city encourages enterprising individuals to innovate.",kr:"그 도시는 진취적인 개인들이 혁신하도록 장려한다."},{t:4,en:"They have an enterprising approach to solving problems.",kr:"그들은 문제 해결에 있어 진취적인 접근 방식을 가지고 있다."},{t:5,en:"An enterprising student started a successful tutoring service.",kr:"한 진취적인 학생이 성공적인 튜터링 서비스를 시작했다."}]},
  "enters": {img:"🚪", ex5:[{t:1,en:"He enters the room quietly.",kr:"그는 조용히 방으로 들어간다."},{t:2,en:"The train enters the tunnel.",kr:"기차가 터널로 들어간다."},{t:3,en:"She enters the competition every year.",kr:"그녀는 매년 대회에 참가한다."},{t:4,en:"A new student enters our class today.",kr:"오늘 새 학생이 우리 반에 들어온다."},{t:5,en:"The key easily enters the lock.",kr:"열쇠가 자물쇠에 쉽게 들어간다."}]},
  "entertain": {img:"🎪", ex5:[{t:1,en:"Clowns entertain kids.",kr:"광대들은 아이들을 즐겁게 한다."},{t:2,en:"The host is entertaining guests.",kr:"진행자가 손님들을 즐겁게 하고 있다."},{t:3,en:"We entertain the crowd.",kr:"우리는 관객을 즐겁게 한다."},{t:4,en:"The show gave us a way to entertain it.",kr:"그 공연은 우리에게 즐겁게 할 방법을 주었다."},{t:5,en:"We entertain the kids well.",kr:"우리는 아이들을 잘 즐겁게 해준다."}]},
  "entertained": {img:"🤡", ex5:[{t:1,en:"The clown entertained the children at the party.",kr:"광대가 파티에서 아이들을 즐겁게 해주었다."},{t:2,en:"She entertained her guests with funny stories.",kr:"그녀는 재미있는 이야기로 손님들을 즐겁게 했다."},{t:3,en:"The street musician entertained the crowd all afternoon.",kr:"거리의 악사가 오후 내내 군중을 즐겁게 했다."},{t:4,en:"We were entertained by his incredible magic tricks.",kr:"우리는 그의 놀라운 마술 묘기에 즐거워했다."},{t:5,en:"The movie entertained us from start to finish.",kr:"그 영화는 시작부터 끝까지 우리를 즐겁게 해주었다."}]},
  "entertainer": {img:"🎤", ex5:[{t:1,en:"The famous entertainer signed autographs for his fans.",kr:"그 유명한 연예인은 팬들에게 사인을 해주었다."},{t:2,en:"She dreams of becoming a professional entertainer one day.",kr:"그녀는 언젠가 전문 연예인이 되는 것을 꿈꾼다."},{t:3,en:"The entertainer told a funny joke that made everyone laugh.",kr:"그 연예인은 모두를 웃게 만드는 재미있는 농담을 했다."},{t:4,en:"Many entertainers attended the charity event last night.",kr:"어젯밤 자선 행사에 많은 연예인들이 참석했다."},{t:5,en:"Being an entertainer requires a lot of hard work and talent.",kr:"연예인이 되는 것은 많은 노력과 재능을 필요로 한다."}]},
  "entertainers": {img:"🎤", ex5:[{t:1,en:"Many talented entertainers performed at the charity concert.",kr:"많은 재능 있는 연예인들이 자선 콘서트에서 공연했다."},{t:2,en:"The show featured popular entertainers from across the country.",kr:"그 쇼에는 전국에서 온 인기 연예인들이 출연했다."},{t:3,en:"Entertainers often face a lot of pressure from the public.",kr:"연예인들은 종종 대중으로부터 많은 압박을 받는다."},{t:4,en:"She dreams of becoming one of the most famous entertainers.",kr:"그녀는 가장 유명한 연예인 중 한 명이 되는 것을 꿈꾼다."},{t:5,en:"The festival invited local entertainers to perform on stage.",kr:"그 축제는 지역 연예인들을 초대하여 무대에서 공연하게 했다."}]},
  "entertaining": {img:"🎭", ex5:[{t:1,en:"The movie was very entertaining from start to finish.",kr:"그 영화는 처음부터 끝까지 매우 재미있었습니다."},{t:2,en:"She is an entertaining speaker who keeps the audience focused.",kr:"그녀는 청중의 집중을 유지하게 하는 재미있는 연설가입니다."},{t:3,en:"It was an entertaining evening with all my friends.",kr:"모든 친구와 함께한 즐거운 저녁이었습니다."},{t:4,en:"The magician gave an entertaining performance at the party.",kr:"마술사가 파티에서 재미있는 공연을 선보였습니다."},{t:5,en:"I find reading mystery novels very entertaining.",kr:"저는 추리 소설을 읽는 것이 매우 재미있다고 생각합니다."}]},
  "entertainment": {img:"🎭", ex5:[{t:1,en:"Entertainment thrives.",kr:"오락 산업이 번창한다."},{t:2,en:"The entertainment is fun.",kr:"그 오락은 즐겁다."},{t:3,en:"We enjoyed the entertainment.",kr:"우리는 그 오락을 즐겼다."},{t:4,en:"The park gave us entertainment.",kr:"그 공원은 우리에게 즐길 거리를 안겼다."},{t:5,en:"We found the entertainment lively.",kr:"우리는 그 오락이 활기차다고 느꼈다."}]},
  "enthrall": {img:"🤩", ex5:[{t:1,en:"The magician enthralled the audience.",kr:"그 마술사가 관객을 매료시켰다."},{t:2,en:"The book enthralled young readers.",kr:"그 책이 어린 독자들을 사로잡았다."},{t:3,en:"The dancer enthralled the whole hall.",kr:"그 무용수가 홀 전체를 매료시켰다."},{t:4,en:"The story enthralled them to the end.",kr:"그 이야기가 그들을 끝까지 사로잡았다."},{t:5,en:"The view enthralled every traveler.",kr:"그 경치가 모든 여행자를 매혹했다."}]},
