  "exploitation": {img:"💰", ex5:[{t:1,en:"The company was accused of worker exploitation.",kr:"그 회사는 노동자 착취로 고발당했다."},{t:2,en:"The development of the natural resources led to exploitation.",kr:"천연자원의 개발은 착취로 이어졌다."},{t:3,en:"We must prevent the exploitation of children.",kr:"우리는 아동 착취를 막아야 한다."},{t:4,en:"The article discussed the exploitation of refugees.",kr:"그 기사는 난민 착취에 대해 논의했다."},{t:5,en:"There is concern about the exploitation of the internet.",kr:"인터넷 착취에 대한 우려가 있다."}]},
  "exploited": {img:"⛓️", ex5:[{t:1,en:"The company exploited its workers for profit.",kr:"그 회사는 이익을 위해 노동자들을 착취했다."},{t:2,en:"They exploited the natural resources of the forest.",kr:"그들은 숲의 천연자원을 착취했다."},{t:3,en:"The hacker exploited a weakness in the software.",kr:"해커는 소프트웨어의 약점을 악용했다."},{t:4,en:"He felt exploited by his business partner.",kr:"그는 사업 파트너에게 이용당했다고 느꼈다."},{t:5,en:"History shows how some nations exploited others.",kr:"역사는 일부 국가들이 어떻게 다른 국가들을 착취했는지 보여준다."}]},
  "exploiting": {img:"⛓️", ex5:[{t:1,en:"The company was accused of exploiting its workers.",kr:"그 회사는 노동자들을 착취했다는 비난을 받았습니다."},{t:2,en:"He is exploiting every opportunity to learn new skills.",kr:"그는 새로운 기술을 배울 수 있는 모든 기회를 활용하고 있습니다."},{t:3,en:"Stop exploiting the natural resources of this land.",kr:"이 땅의 천연자원을 착취하는 것을 멈추세요."},{t:4,en:"They are exploiting the software bug for their own gain.",kr:"그들은 사적인 이익을 위해 소프트웨어 버그를 악용하고 있습니다."},{t:5,en:"The villain is exploiting the hero's kindness.",kr:"악당은 주인공의 친절을 이용해 먹고 있습니다."}]},
  "exploits": {img:"📉", ex5:[{t:1,en:"It is wrong when a company exploits its workers.",kr:"회사가 노동자를 착취하는 것은 잘못된 일입니다."},{t:2,en:"He exploits every opportunity to learn something new.",kr:"그는 새로운 것을 배울 기회를 모두 활용합니다."},{t:3,en:"The software exploits a flaw in the system to gain access.",kr:"그 소프트웨어는 시스템의 결함을 악용하여 접근합니다."},{t:4,en:"History shows how powerful nations exploits weaker ones.",kr:"역사는 강대국이 어떻게 약소국을 착취하는지 보여줍니다."},{t:5,en:"She exploits her natural talent to win competitions.",kr:"그녀는 대회를 이기기 위해 자신의 타고난 재능을 잘 활용합니다."}]},
  "exploration": {img:"🔭", ex5:[{t:1,en:"Exploration drives science.",kr:"탐사는 과학을 이끈다."},{t:2,en:"The exploration is deep.",kr:"그 탐사는 심도 있다."},{t:3,en:"We led an exploration.",kr:"우리는 탐사를 이끌었다."},{t:4,en:"The mission gave us an exploration.",kr:"그 임무는 우리에게 탐사를 안겼다."},{t:5,en:"We found the exploration vast.",kr:"우리는 그 탐사가 방대하다고 느꼈다."}]},
  "exploratory": {img:"🔍", ex5:[{t:1,en:"The team went on an exploratory mission to the forest.",kr:"그 팀은 숲으로 탐사 임무를 떠났다."},{t:2,en:"This is just an exploratory meeting to discuss ideas.",kr:"이것은 아이디어를 논의하기 위한 예비 회의일 뿐이야."},{t:3,en:"They conducted exploratory research before starting the project.",kr:"그들은 프로젝트를 시작하기 전에 탐색적 연구를 수행했다."},{t:4,en:"The robot is used for exploratory purposes in deep caves.",kr:"그 로봇은 깊은 동굴에서 탐사 목적으로 사용된다."},{t:5,en:"He made an exploratory trip to learn more about the culture.",kr:"그는 그 문화를 더 배우기 위해 탐방 여행을 떠났다."}]},
  "explore": {img:"🧭", ex5:[{t:1,en:"Kids explore woods.",kr:"아이들은 숲을 탐험한다."},{t:2,en:"The team is exploring it.",kr:"그 팀이 그것을 탐색하고 있다."},{t:3,en:"We explore the cave.",kr:"우리는 동굴을 탐험한다."},{t:4,en:"The trip gave us a chance to explore it.",kr:"그 여행은 우리에게 탐험할 기회를 주었다."},{t:5,en:"We explore the option full.",kr:"우리는 그 선택지를 충분히 탐색한다."}]},
  "explored": {img:"🗺️", ex5:[{t:1,en:"They explored the ancient ruins for hours.",kr:"그들은 고대 유적지를 몇 시간 동안 탐험했다."},{t:2,en:"We explored every option before making a decision.",kr:"우리는 결정을 내리기 전에 모든 선택지를 탐구했다."},{t:3,en:"The deep sea was explored by scientists.",kr:"심해는 과학자들에 의해 탐험되었다."},{t:4,en:"She explored new ideas for her art project.",kr:"그녀는 미술 프로젝트를 위한 새로운 아이디어를 탐구했다."},{t:5,en:"The children explored the forest behind their house.",kr:"아이들은 집 뒤 숲을 탐험했다."}]},
  "explorer": {img:"🗺️", ex5:[{t:1,en:"The explorer mapped lands.",kr:"탐험가가 땅을 측량했다."},{t:2,en:"The explorer is brave.",kr:"그 탐험가는 용감하다."},{t:3,en:"We met an explorer.",kr:"우리는 탐험가를 만났다."},{t:4,en:"The tale gave us an explorer hero.",kr:"그 이야기는 우리에게 탐험가 영웅을 안겼다."},{t:5,en:"We found the explorer bold.",kr:"우리는 그 탐험가가 대담하다고 느꼈다."}]},
  "explorers": {img:"🧭", ex5:[{t:1,en:"The brave explorers traveled across the frozen Arctic.",kr:"용감한 탐험가들은 얼어붙은 북극을 가로질러 여행했다."},{t:2,en:"Many explorers look for hidden treasures in the jungle.",kr:"많은 탐험가들이 정글에서 숨겨진 보물을 찾는다."},{t:3,en:"Young explorers are learning about the deep ocean.",kr:"어린 탐험가들이 깊은 바다에 대해 배우고 있다."},{t:4,en:"The explorers set up their camp before the sun went down.",kr:"탐험가들은 해가 지기 전에 캠프를 설치했다."},{t:5,en:"Famous explorers have mapped unknown lands for centuries.",kr:"유명한 탐험가들은 수 세기 동안 미지의 땅을 지도에 그려왔다."}]},
  "explores": {img:"🧭", ex5:[{t:1,en:"The documentary explores the mysterious life of deep-sea creatures.",kr:"그 다큐멘터리는 심해 생물들의 신비로운 삶을 탐구합니다."},{t:2,en:"He explores the forest behind his house every weekend.",kr:"그는 매주 주말마다 집 뒤의 숲을 탐험합니다."},{t:3,en:"The book explores the complex relationship between the two main characters.",kr:"그 책은 두 주인공 사이의 복잡한 관계를 탐구합니다."},{t:4,en:"A curious child explores everything in the new room.",kr:"호기심 많은 아이가 새 방에 있는 모든 것을 탐색합니다."},{t:5,en:"The artist explores new painting techniques in his latest series.",kr:"그 예술가는 최근 시리즈에서 새로운 그림 기법을 탐구합니다."}]},
  "exploring": {img:"🗺️", ex5:[{t:1,en:"They spent the day exploring the old castle.",kr:"그들은 그날을 오래된 성을 탐험하며 보냈다."},{t:2,en:"She is exploring new ideas for her project.",kr:"그녀는 프로젝트를 위한 새로운 아이디어를 탐구하고 있다."},{t:3,en:"We are exploring options for our summer vacation.",kr:"우리는 여름휴가를 위한 선택지들을 탐색하고 있다."},{t:4,en:"The scientist is exploring the mysteries of the deep sea.",kr:"그 과학자는 심해의 미스터리를 탐구하고 있다."},{t:5,en:"Children love exploring unknown places in the park.",kr:"아이들은 공원의 미지의 장소를 탐험하는 것을 좋아한다."}]},
