  "vicious": {img:"🐺", ex5:[{t:1,en:"The dog was known for its vicious behavior.",kr:"그 개는 사나운 행동으로 유명했다."},{t:2,en:"They were caught in a vicious cycle of debt.",kr:"그들은 악순환의 빚더미에 빠졌다."},{t:3,en:"He made a vicious comment about her work.",kr:"그는 그녀의 작품에 대해 악랄한 비평을 했다."},{t:4,en:"The fight was quite vicious and scary.",kr:"그 싸움은 매우 사납고 무서웠다."},{t:5,en:"Stay away from that vicious animal.",kr:"저 사나운 동물로부터 멀리 떨어져라."}]},
  "vicissitude": {img:"🎢", ex5:[{t:1,en:"They faced the vicissitudes of life.",kr:"그들은 인생의 부침을 마주했다."},{t:2,en:"Through every vicissitude, she stayed firm.",kr:"온갖 변천 속에서도 그녀는 굳건했다."},{t:3,en:"The firm survived market vicissitudes.",kr:"그 회사는 시장의 변동을 견뎌냈다."},{t:4,en:"He met each vicissitude with calm.",kr:"그는 각 변천을 침착하게 맞았다."},{t:5,en:"The vicissitudes of fate spared no one.",kr:"운명의 부침은 누구도 비껴가지 않았다."}]},
  "vicki": {img:"👤", ex5:[{t:1,en:"Vicki is my best friend from high school.",kr:"비키는 내 고등학교 시절 가장 친한 친구입니다."},{t:2,en:"I sent a birthday card to Vicki yesterday.",kr:"나는 어제 비키에게 생일 카드를 보냈습니다."},{t:3,en:"Vicki likes to play the piano in her free time.",kr:"비키는 여가 시간에 피아노 치는 것을 좋아합니다."},{t:4,en:"Have you seen Vicki at the library today?",kr:"오늘 도서관에서 비키를 봤나요?"},{t:5,en:"Vicki is going to study abroad next semester.",kr:"비키는 다음 학기에 해외로 유학을 갈 예정입니다."}]},
  "vicky": {img:"👩", ex5:[{t:1,en:"Vicky is my best friend from high school.",kr:"비키는 나의 고등학교 단짝 친구입니다."},{t:2,en:"I am going to have dinner with Vicky tonight.",kr:"오늘 밤 비키와 저녁을 먹을 예정입니다."},{t:3,en:"Vicky loves reading books in the park.",kr:"비키는 공원에서 책 읽는 것을 좋아합니다."},{t:4,en:"Did you call Vicky about the party?",kr:"파티에 대해 비키에게 전화했나요?"},{t:5,en:"Vicky helped me finish my project on time.",kr:"비키가 내 프로젝트를 제시간에 끝내도록 도와주었습니다."}]},
  "victim": {img:"🤕", ex5:[{t:1,en:"The flood left many victims homeless.",kr:"그 홍수는 많은 피해자를 집 없게 만들었다."},{t:2,en:"He was a victim of the accident.",kr:"그는 그 사고의 피해자였다."},{t:3,en:"Volunteers helped the earthquake victims.",kr:"자원봉사자들이 지진 피해자들을 도왔다."},{t:4,en:"She fell victim to a clever scam.",kr:"그녀는 교묘한 사기의 희생자가 되었다."},{t:5,en:"The charity supports crime victims.",kr:"그 자선단체는 범죄 피해자들을 지원한다."}]},
  "victimize": {img:"⚖️", ex5:[{t:1,en:"Scammers often try to victimize elderly people who live alone.",kr:"사기꾼들은 종종 혼자 사는 노인들을 희생시키려 한다."},{t:2,en:"We must protect children from those who seek to victimize them.",kr:"우리는 아이들을 희생시키려는 사람들로부터 그들을 보호해야 한다."},{t:3,en:"The new policy unfortunately serves to victimize the poor.",kr:"불행히도 새로운 정책은 가난한 사람들을 희생시키는 결과를 낳는다."},{t:4,en:"He felt like the system was trying to victimize him unfairly.",kr:"그는 시스템이 부당하게 자신을 희생시키려 한다고 느꼈다."},{t:5,en:"Cyberbullying can victimize anyone regardless of their age.",kr:"사이버 불링은 나이와 상관없이 누구든 희생시킬 수 있다."}]},
  "victimized": {img:"🛡️", ex5:[{t:1,en:"He felt victimized by the unfair company policy.",kr:"그는 불공정한 회사 정책에 의해 희생되었다고 느꼈다."},{t:2,en:"The innocent girl was victimized by the online bully.",kr:"그 무고한 소녀는 온라인 괴롭힘의 희생자가 되었다."},{t:3,en:"Small businesses were victimized by the economic crisis.",kr:"소상공인들은 경제 위기로 인해 피해를 입었다."},{t:4,en:"She refused to be victimized by her past mistakes.",kr:"그녀는 과거의 실수에 얽매여 희생당하기를 거부했다."},{t:5,en:"The community stood up for those who were victimized.",kr:"지역 사회는 피해를 입은 사람들을 위해 나섰다."}]},
  "victims": {img:"🛡️", ex5:[{t:1,en:"The charity helps victims of natural disasters.",kr:"그 자선단체는 자연재해 피해자들을 돕는다."},{t:2,en:"The police are interviewing the victims of the crime.",kr:"경찰이 범죄 피해자들을 인터뷰하고 있다."},{t:3,en:"We must support the victims during this difficult time.",kr:"우리는 이 힘든 시기에 피해자들을 지원해야 한다."},{t:4,en:"Many innocent people became victims of the war.",kr:"많은 무고한 사람들이 전쟁의 희생자가 되었다."},{t:5,en:"The report highlights the needs of the victims.",kr:"그 보고서는 피해자들의 요구사항을 강조한다."}]},
  "victor": {img:"🏆", ex5:[{t:1,en:"The victor of the game received a gold medal.",kr:"그 경기의 승자는 금메달을 받았어요."},{t:2,en:"There can be only one victor in this competition.",kr:"이 대회에서 승자는 단 한 명뿐일 수 있어요."},{t:3,en:"He emerged as the victor after a tough fight.",kr:"그는 힘든 싸움 끝에 승자로 떠올랐어요."},{t:4,en:"The victor celebrated with the cheering crowd.",kr:"승자는 환호하는 관중들과 함께 축하했어요."},{t:5,en:"History is often written by the victor.",kr:"역사는 종종 승자에 의해 쓰여져요."}]},
  "victoria": {img:"👑", ex5:[{t:1,en:"Victoria is the name of my favorite park.",kr:"빅토리아는 내가 가장 좋아하는 공원의 이름이다."},{t:2,en:"Victoria moved to London to study fashion.",kr:"빅토리아는 패션을 공부하러 런던으로 이사했다."},{t:3,en:"Have you ever visited Victoria Falls?",kr:"빅토리아 폭포에 가본 적 있니?"},{t:4,en:"Victoria is a very popular name for girls.",kr:"빅토리아는 여자아이들에게 매우 인기 있는 이름이다."},{t:5,en:"I wrote a letter to Victoria yesterday.",kr:"나는 어제 빅토리아에게 편지를 썼다."}]},
  "victorian": {img:"🏛️", ex5:[{t:1,en:"The house was built in the Victorian style.",kr:"그 집은 빅토리아 시대 양식으로 지어졌습니다."},{t:2,en:"She enjoys reading Victorian literature.",kr:"그녀는 빅토리아 시대 문학을 읽는 것을 즐깁니다."},{t:3,en:"The museum displays many Victorian dresses.",kr:"그 박물관은 많은 빅토리아 시대 드레스를 전시합니다."},{t:4,en:"They renovated the old Victorian building last year.",kr:"그들은 작년에 오래된 빅토리아 시대 건물을 개조했습니다."},{t:5,en:"Victorian architecture is known for its intricate details.",kr:"빅토리아 시대 건축은 정교한 세부 장식으로 유명합니다."}]},
  "victories": {img:"🏆", ex5:[{t:1,en:"The team celebrated their recent victories.",kr:"그 팀은 최근의 승리들을 축하했다."},{t:2,en:"She has had many victories in her tennis career.",kr:"그녀는 테니스 경력 동안 많은 승리를 거두었다."},{t:3,en:"History is often written by those who achieve victories.",kr:"역사는 종종 승리를 거둔 자들에 의해 쓰인다."},{t:4,en:"These small victories helped build his confidence.",kr:"이러한 작은 승리들이 그의 자신감을 키우는 데 도움이 되었다."},{t:5,en:"They secured two victories in the tournament.",kr:"그들은 토너먼트에서 두 번의 승리를 확보했다."}]},
